// Config: edit these values for your company; nothing else in the scenario hard-codes them.
// Schedule: set this scenario to run every day at 07:00; Make keeps the schedule outside the blueprint.
return {
  "stop_flag_url": "https://<your stop list API>/stop_flags/R11.1",
  "table_api_url": "https://<your table API for the key log, decision log and exception queue>",
  "workflow_owner": "<your workflow owner>",
  "mailbox_url": "https://<your quotes mailbox API>",
  "vendors_url": "https://<your vendor-record export API>",
  "sheet_url": "https://<your comparison sheet API>",
  "messaging_url": "https://<your messaging API>",
  "response_table_marker": {
    "cell": "<cell holding the response table's title>",
    "text": "<your response table title>"
  },
  "response_table_cells": {
    "supplier": "<cell>",
    "quote_number": "<cell>",
    "quote_date": "<cell>",
    "valid_until": "<cell>",
    "currency": "<cell>",
    "freight": "<cell>",
    "subtotal": "<cell>"
  },
  "response_table_lines": {
    "first_row": "<first line row>",
    "columns": {
      "description": "<column>",
      "quantity": "<column>",
      "unit": "<column>",
      "unit_price": "<column>",
      "line_total": "<column>"
    }
  },
  "delivery_terms": [
    "<your delivery terms that include freight>"
  ],
  "sheet_currency": [
    "<your sheet currency, as quotes print it>"
  ],
  "unit_table": [
    {
      "unit": "<unit as quoted>",
      "base_unit": "<base unit>",
      "factor": 1
    }
  ],
  "margin_working_days": 5,
  "price_off_pct": 30,
  "stockroom_lead": "<your stockroom lead>",
  "editor": "<your workflow editor>",
  "ai_model": "claude-haiku-5-5",
  "ai_inference_geo": "us",
  "ai_url": "https://api.anthropic.com/v1/messages"
};

// Adapter: the rule below is the same JavaScript as the recipe's n8n build.
// $('Step name') answers from this step's inputs: each is that step's output in this scenario.
const SOURCES = {"Config": "in0_Config", "Read unchecked AI-filled rows": "in1_ReaduncheckedAIfilledrow"};
const LISTS = [];
const EXECUTED = [];
const DATA = {};
for (const [node, key] of Object.entries(SOURCES)) {
  const raw = input[key];
  let v = raw;
  if (typeof raw === 'string') { try { v = JSON.parse(raw); } catch (e) { v = raw; } }
  DATA[node] = LISTS.includes(node) ? (v || []).map(i => (i && i.json !== undefined ? i : { json: i })) : [{ json: v }];
}
const $ = (node) => {
  const ran = node in DATA || EXECUTED.includes(node);
  const list = () => { if (!(node in DATA)) throw new Error(`step ${node} has no data in this scenario`); return DATA[node]; };
  return { isExecuted: ran, first: () => list()[0], last: () => list()[list().length - 1], all: () => list(),
           get item() { return list()[0]; } };
};
const INPUT = "Read unchecked AI-filled rows";
const $input = { all: () => $(INPUT).all(), first: () => $(INPUT).first(), last: () => $(INPUT).last(), get item() { return $(INPUT).first(); } };
const $execution = { id: input.run_id };
const BODIES = (out) => ({"message": out.text ? JSON.stringify({ to: $('Config').first().json.stockroom_lead, subject: 'Quote rows to check this shift', text: out.text }) : null});
const one = (r) => (Array.isArray(r) ? r : [r]).filter(Boolean).map(i => (i.json !== undefined ? i.json : i));
const $json = INPUT && INPUT in DATA ? $input.first().json : {};
const __rule = () => {
// Step 12: tell the stockroom lead which AI-filled rows still wait for a check against their page.
const rows = $('Read unchecked AI-filled rows').first().json.items || [];
if (!rows.length) return [];
const quotes = [...new Set(rows.map(r => `${r.supplier} ${r.quote_number} (${r.message_link || r.message_id})`))];
return [{ json: { count: rows.length, text: `${rows.length} AI-filled rows to check against their pages, then mark "checked": ${quotes.join('; ')}` } }];
};
const out = one(__rule())[0] || {};
return Object.assign({}, out, BODIES(out));
